  "skeleton-v2": "import { SkeletonV2, SkeletonText, SkeletonCard } from \"@/components/ui/skeleton-v2\";\n\n<SkeletonV2 className=\"h-4 w-48\" />\n<SkeletonText lines={3} />\n<SkeletonCard className=\"w-72\" />",
